#[test]
fn truth_table_exact_grouped_alternative_string_classes_preserve_deep_required_empty_and_padded_counts()
 {
    let pattern = JsString::from(
        format!(
            r"{}((^)|(\b))(?<c>[\q{{|a|ab}}])|((\b\B)|(\b\B)){}",
            "(".repeat(1000),
            "){1}?".repeat(1000)
        )
        .as_str(),
    );
    check(&format!(
        "var r=new RegExp({pattern:?},'dv'),m=r.exec('ab'),n=r.exec('');m[0]==='ab'&&m.length===1008&&m[1]==='ab'&&m[1000]==='ab'&&m[1002]===''&&m[1003]===undefined&&m.groups.c==='ab'&&m[1005]===undefined&&m.indices[1][0]===0&&m.indices[1][1]===2&&m.indices.groups.c===m.indices[1004]&&n[0]===''&&n[1]===''&&n[1000]===''&&n.groups.c===''&&n.indices[1][0]===0&&n.indices[1][1]===0"
    ));
    check(
        r"var r=/(?<outer>((^)|(\b))(?<c>[\q{ab!|a}])((^)|(\B))|((\b\B)|(\b\B))){0001,0001}?/dv,m=r.exec('ab!Z');m[0]==='a'&&m.groups.outer==='a'&&m.groups.c==='a'&&m.indices.groups.outer===m.indices[1]&&m.indices[1][0]===0&&m.indices[1][1]===1",
    );
    check(
        r"var r=/(?<outer>((\b\B)|(\b\B))()|(($)|(\b))(?<c>[\q{}])){1}/dvg,m=r.exec('!a');m[0]===''&&m.index===1&&m.groups.outer===''&&m.groups.c===''&&m[2]===undefined&&m[5]===undefined&&m[8]===''&&m.indices.groups.c===m.indices[9]&&m.indices.groups.outer===m.indices[1]&&m.indices[1][0]===1&&m.indices[1][1]===1&&r.lastIndex===1",
    );
    let one = "0".repeat(1000) + "1";
    let pattern = JsString::from(
        format!(r"(?<outer>((\b)|(\B))(?<e>)|((^)|(\b))(?<c>[\q{{|a|ab}}])){{{one},{one}}}?")
            .as_str(),
    );
    check(&format!(
        "var r=new RegExp({pattern:?},'dv'),m=r.exec('ab');m[0]===''&&m.groups.outer===''&&m.groups.e===''&&m.groups.c===undefined&&m.indices.groups.outer===m.indices[1]&&m.indices.groups.e===m.indices[5]"
    ));
    let word = "x".repeat(20_000);
    let pattern=JsString::from(format!(r"(?<outer>((^)|(\b))(?<c>[\p{{Any}}\q{{{word}|{word}x}}])(($)|(\B))|((\b\B)|(\b\B))()){{{one}}}").as_str());
    let input = JsString::from(word.as_str());
    check(&format!(
        "var r=new RegExp({pattern:?},'dv'),m=r.exec({input:?}),n=r.exec('x');m[0].length===20000&&m.groups.outer.length===20000&&m.groups.c.length===20000&&m.indices.groups.outer===m.indices[1]&&m.indices[1][0]===0&&m.indices[1][1]===20000&&n[0]==='x'&&n.groups.outer==='x'&&n.groups.c==='x'"
    ));
    let mut realm = Realm::new(Limits {
        max_steps: Some(30_000),
        ..Limits::default()
    });
    realm.eval("var r=7,marker=0").unwrap();
    assert!(matches!(
        realm.eval(&format!(
            "try{{r=new RegExp({pattern:?},'v')}}catch{{marker=1}}finally{{marker=2}}"
        )),
        Err(Error::Limit { .. })
    ));
    assert_eq!(realm.eval("r===7&&marker===0"), Ok(Value::Boolean(true)));
}
#[test]
fn truth_table_exact_grouped_alternative_string_classes_prove_unknown_branches_and_other_wrapper_counts()
 {
    assert_eq!(Realm::default().eval(r####"var pattern="^(((^)|(\\b))([\\q{a|ab}])|()){1}",input="aba",r=new RegExp(pattern,"dv"),m=r.exec(input);r.source===pattern&&r.flags==="dv"&&r.hasIndices&&r.unicodeSets&&(m===null||(m.input===input&&m.groups===undefined&&m.indices.groups===undefined&&Object.hasOwn(m,"groups")&&Object.hasOwn(m.indices,"groups")))&&JSON.stringify(m===null?null:[Array.from(m,v=>v===undefined?"<undefined>":v),Array.from(m.indices,v=>v===undefined?"<undefined>":v),m.index,r.lastIndex])==="[[\"ab\",\"ab\",\"\",\"\",\"<undefined>\",\"ab\",\"<undefined>\"],[[0,2],[0,2],[0,0],[0,0],\"<undefined>\",[0,2],\"<undefined>\"],0,0]""####),Ok(Value::Boolean(true)));
    for pattern in [
        r"(((\b\B)|(\b\B))([\q{ab}&&\p{RGI_Emoji}])|()){1}",
        r"(((\b\B)|(\b\B))([\q{|a|ab}])|((\b\B)|(\b\B))z){1}",
        r"(((^)|(\b))([\q{a|ab}])|\1){1}",
        r"(((^)|(\b))([\q{a|ab}])|([a])){1}",
        r"(((^)|(\b))([\q{a|ab}])|()){2}",
        r"(((^)|(\b))([\q{a|ab}])|()){1,2}",
    ] {
        let pattern = JsString::from(pattern);
        let mut realm = Realm::default();
        assert!(matches!(realm.eval(&format!("var marker=0;try{{new RegExp({pattern:?},'v').test('aba')}}catch{{marker=1}}finally{{marker=2}}")),Err(Error::Unsupported{..})),"{pattern:?}");
        assert_eq!(realm.eval("marker"), Ok(Value::Number(0.0)));
    }
}
